/* Add Cataclysm starting equipment for worgen and goblin, and allows worgen/goblin rogues to use axes/maces, respectively */
/* Goblin */
DELETE FROM `item_template` WHERE  `entry` IN (49528, 49524, 49527, 49529, 49502, 49503, 49504, 52532, 49514, 49515, 49516, 49510, 49512, 49531, 52550, 52551, 52552, 49505, 49506, 49508, 49520, 49521, 49522); -- Goblin starting gear

/* Grants all newly created goblin rogues the ability to use their starting weapon */
/* Goblin rogues start with a mace, but rogues don't start with the weapon skill learned by default */
DELETE FROM `playercreateinfo_skills` WHERE `raceMask` = @GoblinMask AND `classMask` = @RogueMask;
